import 'type_registry.dart';

/// Emits deterministic, explicit registration for every retired identifier.
String emitTombstoneFile(TypeIdRegistry registry) {
  final ids = registry.retiredTypeIds.keys.toList()..sort();
  return '''
// GENERATED CODE - DO NOT MODIFY BY HAND
// Generated by `dart run phive_generator:assign_type_ids` from
// phive_type_registry.json. Call registerPHiveTombstones() at startup, after
// registering adapters, so retired type IDs read as schema drift.
// ignore_for_file: type=lint

import 'package:phive/phive.dart';

${ids.map((id) => 'final class _PHiveRetired$id {}').join('\n')}

/// Registers a tombstone for every retired type ID. Idempotent.
void registerPHiveTombstones() {
${ids.map((id) => '  registerPHiveTombstone<_PHiveRetired$id>($id);').join('\n')}
}
''';
}
